class InvoiceRepository                  # plain Ruby (PORO) over ActiveRecord
  def find_overdue(on) = Invoice.where(due: ...on).includes(:lines).to_a   # relation stays here
  def find(id) = Invoice.find_by(id: id)&.then { |row| to_domain(row) }
  def add(invoice) = Invoice.create!(id: invoice.id, amount: invoice.amount, due: invoice.due)
end
